// Turns the incoming batch into stable dedup keys and builds the two Supabase REST
// URLs the next nodes call. Config lives here so there is a single place to edit.
const SUPABASE_URL = '';        // TODO: https://<project>.supabase.co
const PREVIEW_LIMIT = 200;      // never store more of the payload than this

const input = $input.first().json || {};
const source = String(input.source || '').trim();
const keyField = String(input.key_field || '').trim();
const items = Array.isArray(input.items) ? input.items : [];

if (!source) throw new Error('source is required');
if (!keyField) throw new Error('key_field is required');
if (!SUPABASE_URL) throw new Error('SUPABASE_URL is not configured in "Build keys"');

// SHA-256 in plain JavaScript. The Code node sandbox on this instance has no crypto
// global and refuses builtin module imports, so the digest has to be computed by hand.
// Output is a standard SHA-256 digest in lowercase hex, identical to any other implementation.
const sha256 = (message) => {
  const K = [
    0x428a2f98, 0x71374491, 0xb5c0fbcf, 0xe9b5dba5, 0x3956c25b, 0x59f111f1, 0x923f82a4, 0xab1c5ed5,
    0xd807aa98, 0x12835b01, 0x243185be, 0x550c7dc3, 0x72be5d74, 0x80deb1fe, 0x9bdc06a7, 0xc19bf174,
    0xe49b69c1, 0xefbe4786, 0x0fc19dc6, 0x240ca1cc, 0x2de92c6f, 0x4a7484aa, 0x5cb0a9dc, 0x76f988da,
    0x983e5152, 0xa831c66d, 0xb00327c8, 0xbf597fc7, 0xc6e00bf3, 0xd5a79147, 0x06ca6351, 0x14292967,
    0x27b70a85, 0x2e1b2138, 0x4d2c6dfc, 0x53380d13, 0x650a7354, 0x766a0abb, 0x81c2c92e, 0x92722c85,
    0xa2bfe8a1, 0xa81a664b, 0xc24b8b70, 0xc76c51a3, 0xd192e819, 0xd6990624, 0xf40e3585, 0x106aa070,
    0x19a4c116, 0x1e376c08, 0x2748774c, 0x34b0bcb5, 0x391c0cb3, 0x4ed8aa4a, 0x5b9cca4f, 0x682e6ff3,
    0x748f82ee, 0x78a5636f, 0x84c87814, 0x8cc70208, 0x90befffa, 0xa4506ceb, 0xbef9a3f7, 0xc67178f2,
  ];
  const bytes = new TextEncoder().encode(message);
  const bitLen = bytes.length * 8;
  const padded = new Uint8Array(((bytes.length + 9 + 63) >> 6) << 6);
  padded.set(bytes);
  padded[bytes.length] = 0x80;
  const view = new DataView(padded.buffer);
  view.setUint32(padded.length - 8, Math.floor(bitLen / 0x100000000));
  view.setUint32(padded.length - 4, bitLen >>> 0);
  const H = [0x6a09e667, 0xbb67ae85, 0x3c6ef372, 0xa54ff53a, 0x510e527f, 0x9b05688c, 0x1f83d9ab, 0x5be0cd19];
  const W = new Uint32Array(64);
  const rotr = (x, n) => (x >>> n) | (x << (32 - n));
  for (let off = 0; off < padded.length; off += 64) {
    for (let i = 0; i < 16; i++) W[i] = view.getUint32(off + i * 4);
    for (let i = 16; i < 64; i++) {
      const s0 = rotr(W[i - 15], 7) ^ rotr(W[i - 15], 18) ^ (W[i - 15] >>> 3);
      const s1 = rotr(W[i - 2], 17) ^ rotr(W[i - 2], 19) ^ (W[i - 2] >>> 10);
      W[i] = (W[i - 16] + s0 + W[i - 7] + s1) >>> 0;
    }
    let [a, b, c, d, e, f, g, h] = H;
    for (let i = 0; i < 64; i++) {
      const S1 = rotr(e, 6) ^ rotr(e, 11) ^ rotr(e, 25);
      const t1 = (h + S1 + ((e & f) ^ (~e & g)) + K[i] + W[i]) >>> 0;
      const S0 = rotr(a, 2) ^ rotr(a, 13) ^ rotr(a, 22);
      const t2 = (S0 + ((a & b) ^ (a & c) ^ (b & c))) >>> 0;
      h = g; g = f; f = e; e = (d + t1) >>> 0; d = c; c = b; b = a; a = (t1 + t2) >>> 0;
    }
    H[0] = (H[0] + a) >>> 0; H[1] = (H[1] + b) >>> 0; H[2] = (H[2] + c) >>> 0; H[3] = (H[3] + d) >>> 0;
    H[4] = (H[4] + e) >>> 0; H[5] = (H[5] + f) >>> 0; H[6] = (H[6] + g) >>> 0; H[7] = (H[7] + h) >>> 0;
  }
  return H.map((x) => x.toString(16).padStart(8, '0')).join('');
};

const keys = [];
for (const item of items) {
  const raw = item === null || item === undefined ? '' : item[keyField];
  if (raw === undefined || raw === null || String(raw) === '') {
    throw new Error('item is missing key_field "' + keyField + '": ' + JSON.stringify(item).slice(0, 120));
  }
  const value = String(raw);
  keys.push({
    hash: sha256(source + ':' + value),
    value,
    item,
    preview: JSON.stringify(item).slice(0, PREVIEW_LIMIT),
  });
}

// Deduplicate inside the batch itself: the same key twice in one call is one item.
const seenInBatch = new Set();
const unique = keys.filter((k) => (seenInBatch.has(k.hash) ? false : seenInBatch.add(k.hash)));
const duplicatesInBatch = keys.length - unique.length;

const base = SUPABASE_URL.replace(/\/+$/, '');
const hashList = unique.map((k) => '"' + k.hash + '"').join(',');

return [{
  json: {
    source,
    keyField,
    total: items.length,
    duplicatesInBatch,
    keys: unique,
    // PostgREST: hash=in.("a","b"). An empty batch must not produce in.() which is invalid.
    selectUrl: base + '/rest/v1/seen_items?select=hash&hash=in.(' + (hashList || '"__none__"') + ')',
    insertUrl: base + '/rest/v1/seen_items',
  },
}];

// Subtracts the hashes the database already knows from the batch.
const built = $('Build keys').first().json;
const seen = new Set(
  $input.all().map((i) => i.json && i.json.hash).filter((h) => typeof h === 'string')
);

const fresh = built.keys.filter((k) => !seen.has(k.hash));
const now = new Date().toISOString();

return [{
  json: {
    source: built.source,
    hasNew: fresh.length > 0,
    new_items: fresh.map((k) => k.item),
    skipped: built.total - fresh.length,
    duplicatesInBatch: built.duplicatesInBatch,
    // One batch insert, never one call per item.
    rows: fresh.map((k) => ({
      hash: k.hash,
      source: built.source,
      first_seen_at: now,
      payload_preview: k.preview,
    })),
  },
}];

// Both branches converge here, so the caller always gets the same shape whether or
// not an insert happened.
const d = $('Diff against seen').first().json;
return [{
  json: {
    source: d.source,
    new_items: d.new_items,
    skipped: d.skipped,
    duplicates_in_batch: d.duplicatesInBatch,
  },
}];
